
(function(root){
  'use strict';
  const COMPONENT='data-verdict-state-component';
  const DICT={
    fr:{title:'Mes connexions',intro:'Verdict montre uniquement ce qui répond réellement.',open:'Connexions',close:'Fermer',refresh:'Vérifier maintenant',non_verifie:'Pas encore raccordé',verifie:'Vérifié',donnees_anciennes:'Données anciennes',hors_ligne:'Service injoignable pour l’instant',erreur:'Réponse en erreur',server:'Serveur non branché'},
    en:{title:'My connections',intro:'Verdict only shows services that actually respond.',open:'Connections',close:'Close',refresh:'Check now',non_verifie:'Not connected yet',verifie:'Verified',donnees_anciennes:'Old data',hors_ligne:'Service currently unreachable',erreur:'Error response',server:'Server not connected'},
    es:{title:'Mis conexiones',intro:'Verdict solo muestra lo que responde realmente.',open:'Conexiones',close:'Cerrar',refresh:'Comprobar ahora',non_verifie:'Aún sin conectar',verifie:'Verificado',donnees_anciennes:'Datos antiguos',hors_ligne:'Servicio no disponible por ahora',erreur:'Respuesta con error',server:'Servidor no conectado'},
    it:{title:'Le mie connessioni',intro:'Verdict mostra solo ciò che risponde davvero.',open:'Connessioni',close:'Chiudi',refresh:'Verifica ora',non_verifie:'Non ancora collegato',verifie:'Verificato',donnees_anciennes:'Dati precedenti',hors_ligne:'Servizio al momento non raggiungibile',erreur:'Risposta con errore',server:'Server non collegato'},
    de:{title:'Meine Verbindungen',intro:'Verdict zeigt nur Dienste, die wirklich antworten.',open:'Verbindungen',close:'Schließen',refresh:'Jetzt prüfen',non_verifie:'Noch nicht verbunden',verifie:'Geprüft',donnees_anciennes:'Ältere Daten',hors_ligne:'Dienst derzeit nicht erreichbar',erreur:'Fehlerhafte Antwort',server:'Server nicht verbunden'},
    nl:{title:'Mijn koppelingen',intro:'Verdict toont alleen diensten die echt antwoorden.',open:'Koppelingen',close:'Sluiten',refresh:'Nu controleren',non_verifie:'Nog niet gekoppeld',verifie:'Geverifieerd',donnees_anciennes:'Oude gegevens',hors_ligne:'Dienst tijdelijk onbereikbaar',erreur:'Fout antwoord',server:'Server niet gekoppeld'},
    pt:{title:'As minhas ligações',intro:'A Verdict só mostra serviços que respondem de facto.',open:'Ligações',close:'Fechar',refresh:'Verificar agora',non_verifie:'Ainda não ligado',verifie:'Verificado',donnees_anciennes:'Dados antigos',hors_ligne:'Serviço indisponível de momento',erreur:'Resposta com erro',server:'Servidor não ligado'}
  };
  function language(){const value=(document.documentElement.lang||'fr').slice(0,2).toLowerCase();return DICT[value]?value:'fr'}
  function esc(value){return String(value==null?'':value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
  function defaults(){return [{id:'chift',nom:'Caisse',etat:'non_verifie',detail:'connexion_non_verifiee'},{id:'iopole',nom:'Factures électroniques',etat:'non_verifie',detail:'connexion_non_verifiee'},{id:'backend',nom:'Sauvegarde serveur',etat:'non_verifie',detail:'serveur_non_branche'}]}
  function label(item,t){if(item.etat==='verifie'&&item.verifie_le)return t.verifie+' · '+new Date(item.verifie_le).toLocaleString();if(item.detail==='serveur_non_branche')return t.server;return t[item.etat]||t.non_verifie}
  function render(items){const t=DICT[language()],list=document.getElementById('r18-connect-list');list.innerHTML=items.map(item=>'<article class="r18-connect-card"><h3>'+esc(item.nom||item.id)+'</h3><span class="r18-state" data-state="'+esc(item.etat||'non_verifie')+'">'+esc(label(item,t))+'</span>'+(item.etat==='erreur'&&item.code?'<p>'+esc(item.code)+'</p>':'')+'</article>').join('')}
  async function load(){let items=defaults();try{const response=await fetch('/api/v1/client/branchements',{credentials:'same-origin'});if(response.ok){const data=await response.json();if(Array.isArray(data.branchements))items=data.branchements}}catch(error){}render(items)}
  /* C343 (décisions 25, 26, 29) : plus de bouton ↔ dans l'en-tête ; la feuille reste installée (même sans .shell-actions : Inventaire
     gratuit, lien d'équipe) et s'ouvre depuis Paramètres par VerdictConnectionsR18.ouvrir(), dans la langue du moment. */
  function install(){if(document.getElementById('r18-connections')||!document.body)return;const layer=document.createElement('div');layer.id='r18-connections';layer.className='r18-connect-layer';layer.hidden=true;layer.setAttribute(COMPONENT,'true');layer.innerHTML='<section class="r18-connect-sheet" role="dialog" aria-modal="true" aria-labelledby="r18-connect-title"><header class="r18-connect-head"><div><h2 id="r18-connect-title"></h2><p class="r18-connect-intro"></p></div><button class="r18-connect-close" type="button">×</button></header><div id="r18-connect-list" class="r18-connect-list"></div><button class="r18-connect-refresh" type="button"></button></section>';document.body.appendChild(layer);let retour=null;const close=()=>{layer.hidden=true;try{if(retour&&retour.focus)retour.focus()}catch(e){}};layer.querySelector('.r18-connect-close').addEventListener('click',close);layer.addEventListener('click',event=>{if(event.target===layer)close()});layer.querySelector('.r18-connect-refresh').addEventListener('click',load);layer.__ouvrir=()=>{const t=DICT[language()],c=layer.querySelector('.r18-connect-close');layer.querySelector('#r18-connect-title').textContent=t.title;layer.querySelector('.r18-connect-intro').textContent=t.intro;c.setAttribute('aria-label',t.close);layer.querySelector('.r18-connect-refresh').textContent=t.refresh;retour=document.activeElement;layer.hidden=false;load();c.focus()}}
  function ouvrir(){install();const l=document.getElementById('r18-connections');if(l&&l.__ouvrir){l.__ouvrir();return true}return false}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
  root.VerdictConnectionsR18=Object.freeze({DICT,defaults,label,render,load,install,ouvrir});
})(typeof globalThis!=='undefined'?globalThis:this);

